def prepare():
    lang = materialize()
    delta = read(PROJECT / 'lexical-delta.json')
    added = []

    def add(key, entry, gloss):
        if key in delta['entries']:
            return
        assert key not in lang.lexicon, key
        entry.update(semanticId='lex.' + key, usageScope='later-standard',
                     status='authored', historicalForms=[])
        if key == 'arm_gaunt_literary':
            entry.update(usageScope='editorial-exception', productive=False,
                         uncertainSourceReading=True)
        delta['entries'][key] = entry
        delta['glosses'][key] = gloss
        added.append(key)

    for key, (parent, gloss, pos, meaning) in CONTEXTS.items():
        entry = deepcopy(lang.lexicon[parent])
        entry.update(pos=pos, meaning=meaning,
                     origin='Reviewed contextual sense/identity of ' + parent)
        add(key, entry, gloss)
    available = {**lang.lexicon, **delta['entries']}
    for key, (parents, pos, gloss, meaning) in DERIVATIONS.items():
        form = ''.join(available[p]['form'] for p in parents)
        if key == 'armour_craftsman':
            # A free equipment modifier plus craft-person, like the inherited
            # multiword military titles; do not agglutinate the whole phrase.
            form = available[parents[0]]['form'] + ' ' + available[parents[1]]['form']
        if pos == 'agent':
            form += lang.suffix['ag'][0]
            pos = 'noun'
        add(key, dict(form=form, roman=lang.reading(form), pos=pos,
                     meaning=meaning, derivationKeys=parents,
                     origin='Authored native derivation: ' + ' + '.join(parents)), gloss)
    for key, (form, gloss, meaning) in NAMES.items():
        add(key, dict(form=form, roman=lang.reading(form), pos='proper',
                     meaning=meaning,
                     origin='Author-permitted phonetic adaptation of a personal or place name.'), gloss)
    add('cock_fowl', dict(form='keklen', roman=lang.reading('keklen'), pos='noun',
        meaning='Adult male domestic fowl, the fighting cock in Antony’s comparison. A deliberate lexical counterpart to native hen kekla; the ending is not a productive sex-changing suffix.',
        origin='Authored native bird-family coinage related to kekla, replacing a suspicious English-like ordinary form only in this new working translation.'), 'cock')
    inch = quantity(1, 'fraction', 12)['form'] + ' ' + lang.lexicon['foot']['form']
    add('inch_measure', dict(form=inch, roman=lang.reading(inch), pos='noun',
        meaning='An inch, one twelfth of the source foot, expressed as an exact Unta spoken fraction plus foot. The fortune/body joke retains the measure; no modern millimetre standard is imposed on the early source.',
        origin='Exact native Unta 1/12 plus the source-culture length sense of foot.',
        numericValue='1/12', numericKind='length-in-source-feet', numericNotation='words', base12='0.1'), 'inch')
    if added:
        delta['decisions'].append(dict(work='antony-and-cleopatra', decision=
            'Preserve speaker-specific reference, political and erotic metaphors, and dramatic repetitions. '
            'Antony, Antonius, Octavian and the Roman Demetrius have explicit identities; no lookup labels print as names. '
            'Source figures use Unta figures; source quantity words use Unta words, including triple and twain.'))
    write(PROJECT / 'lexical-delta.json', delta)
    materialize()
    print('Antony lexical additions:', len(added))


if __name__ == '__main__':
    prepare()
